import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { index?: number; wordIndex?: number; startFrame?: number; endFrame?: number; text?: string; word?: string };
type ShotProps = { wordCues?: WordCue[] };

const C = {
  porcelain: "#F3F6F4", oceanPale: "#DCECF3", ink: "#142D40",
  blue: "#246BFD", electric: "#0066FF", cyan: "#28AFCD",
  coral: "#F16D59", emerald: "#198A71", amber: "#D59B25"
};
const FALLBACK = [0, 14, 32, 50, 67, 85, 103, 121, 139, 157, 174, 192, 210, 228, 246, 264, 306, 326, 345, 364, 384, 403, 422];
const clamp = (v: number, low = 0, high = 1) => Math.min(high, Math.max(low, v));
const smooth = (v: number) => { const t = clamp(v); return t * t * (3 - 2 * t); };
const ease = Easing.inOut(Easing.cubic);
const glow = "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(20,45,64,0.10)";
const labelFont = '"IBM Plex Sans", "Arial", sans-serif';
const headingFont = '"Manrope", "Arial", sans-serif';

// Exactly eight visible shapes: three blades, hub, rim, two supports, pedestal.
const FanIllustration: React.FC<{ angle: number; reveal: number; stopped: number; frame: number }> = ({ angle, reveal, stopped, frame }) => {
  const breath = 0.92 + Math.sin(frame * 0.037) * 0.035;
  const blade = "M 296 170 C 262 150 239 96 260 45 C 268 24 292 27 306 46 C 338 91 353 134 316 165 C 310 171 304 173 296 170 Z";
  return (
    <svg width={600} height={390} viewBox="0 0 600 390" style={{ position: "absolute", inset: 0, overflow: "visible", opacity: reveal }} aria-label="Translucent three-blade fan, a visual analogy for cooling winds">
      <defs>
        <linearGradient id="s01-blade" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0.94" />
          <stop offset="36%" stopColor="#6DD9EA" stopOpacity="0.7" />
          <stop offset="100%" stopColor={C.cyan} stopOpacity="0.28" />
        </linearGradient>
        <radialGradient id="s01-hub" cx="34%" cy="26%" r="80%">
          <stop offset="0%" stopColor="#FFFFFF" />
          <stop offset="50%" stopColor="#C1EDF4" />
          <stop offset="100%" stopColor={C.cyan} />
        </radialGradient>
        <linearGradient id="s01-stand" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0.88" />
          <stop offset="100%" stopColor={C.cyan} stopOpacity="0.25" />
        </linearGradient>
        <filter id="mgGlow" x="-60%" y="-60%" width="220%" height="220%" colorInterpolationFilters="sRGB">
          <feGaussianBlur in="SourceGraphic" stdDeviation="3.5" result="fanBlur" />
          <feMerge><feMergeNode in="fanBlur" /><feMergeNode in="SourceGraphic" /></feMerge>
        </filter>
      </defs>
      <ellipse cx="300" cy="349" rx="93" ry="15" fill="url(#s01-stand)" stroke={C.electric} strokeOpacity="0.35" strokeWidth="2" />
      <rect x="279" y="269" width="42" height="78" rx={20} ry={20} fill="url(#s01-stand)" stroke={C.electric} strokeOpacity="0.44" strokeWidth="2" />
      <rect x="237" y="323" width="126" height="26" rx={20} ry={20} fill="url(#s01-stand)" stroke={C.electric} strokeOpacity="0.4" strokeWidth="2" />
      <circle cx="300" cy="165" r="143" fill="rgba(255,255,255,0.16)" stroke={C.electric} strokeOpacity={0.36 + stopped * 0.14} strokeWidth="3" filter="url(#mgGlow)" />
      <g transform={'rotate(' + angle + ' 300 165)'} opacity={breath}>
        <path d={blade} fill="url(#s01-blade)" stroke={C.electric} strokeWidth="2.5" strokeLinejoin="round" />
        <path d={blade} transform="rotate(120 300 165)" fill="url(#s01-blade)" stroke={C.electric} strokeWidth="2.5" strokeLinejoin="round" />
        <path d={blade} transform="rotate(240 300 165)" fill="url(#s01-blade)" stroke={C.electric} strokeWidth="2.5" strokeLinejoin="round" />
      </g>
      <circle cx="300" cy="165" r="24" fill="url(#s01-hub)" stroke={C.electric} strokeWidth="3" filter="url(#mgGlow)" />
    </svg>
  );
};

const Selection: React.FC<{ x: number; y: number; width: number; height: number; opacity: number; color: string; frameAt: number }> = ({ x, y, width, height, opacity, color, frameAt }) => (
  <div style={{ position: "absolute", left: x, top: y, width, height, borderRadius: 24, opacity, pointerEvents: "none" }}>
    <mg.FocusFrame color={color} borderRadius={24} frameAt={frameAt} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", borderRadius: 24 }}>
      <div style={{ width, height, borderRadius: 24, border: '1.5px solid ' + color, boxShadow: '0 0 24px ' + color + '28', boxSizing: "border-box" }} />
    </mg.FocusFrame>
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueAt = (i: number) => {
    const explicit = cues.find(c => c.wordIndex === i || c.index === i);
    return explicit?.startFrame ?? cues[i]?.startFrame ?? FALLBACK[i] ?? 0;
  };
  const giantAt = cueAt(4);
  const fanAt = cueAt(6);
  const coolAt = cueAt(9);
  const eastAt = cueAt(11);
  const suddenAt = cueAt(13);
  const stopAt = cueAt(14);
  const workingAt = cueAt(15);
  const andAt = cueAt(16);
  const exactlyAt = cueAt(18);
  const happeningAt = cueAt(20);
  const rightAt = cueAt(21);
  const nowAt = cueAt(22);
  const stopEnd = Math.max(workingAt + 18, suddenAt + 1);
  const pullEnd = nowAt + 20;
  const f = Math.min(frame, durationInFrames - 1);

  const timeLerp = (a: number, b: number, from: number, to: number) => interpolate(f, [a, Math.max(a + 1, b)], [from, to], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
  const enter = (at: number, damping = 14) => spring({ frame: f - at, fps, config: { damping, stiffness: 160, mass: 0.8 } });
  const attention = (at: number, end: number) => interpolate(f, [at, at + 7, end - 8, end], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  let zoom = timeLerp(0, suddenAt, 1, 1.06);
  let panX = 0;
  let panY = 0;
  if (f >= suddenAt) {
    zoom = timeLerp(suddenAt, stopEnd, 1.06, 1.22);
    panX = timeLerp(suddenAt, stopEnd, 0, -120);
    panY = timeLerp(suddenAt, stopEnd, 0, -55);
  }
  if (f >= stopEnd && f < nowAt) {
    const drift = smooth((f - stopEnd) / Math.max(1, nowAt - stopEnd));
    zoom = 1.22 - 0.002 * drift;
    panX = -120 + 2 * drift;
    panY = -55 + 1 * drift;
  }
  if (f >= nowAt) {
    zoom = timeLerp(nowAt, pullEnd, 1.218, 1.15);
    panX = timeLerp(nowAt, pullEnd, -118, -80);
    panY = timeLerp(nowAt, pullEnd, -54, -35);
  }

  // An analytic angular integral: smooth braking, no discontinuity or reverse spin.
  const brakeDuration = stopEnd - suddenAt;
  const t = clamp((f - suddenAt) / brakeDuration);
  const beforeBrake = Math.min(f, suddenAt);
  const angle = -18 - 7.4 * (beforeBrake + brakeDuration * (t - t * t + t * t * t / 3));
  const stopped = smooth((f - stopAt) / Math.max(1, stopEnd - stopAt));
  const disruption = smooth((f - suddenAt) / brakeDuration);
  const fanSpring = enter(giantAt, 16);
  const fanScale = 0.94 + 0.06 * fanSpring;
  const fanOpacity = timeLerp(0, 22, 0.4, 1);
  const analogyOpacity = timeLerp(0, 10, 0.7, 1);
  const laneReveal = clamp(enter(fanAt));

  // Air continues westward even after the symbolic rotor stops.
  const windIntegral = Math.min(f, suddenAt) + brakeDuration * (t - 0.64 * (t * t * t - 0.5 * t * t * t * t)) + Math.max(0, f - stopEnd) * 0.36;
  const travel = windIntegral * 5.25;
  const windLabelMix = smooth((f - exactlyAt) / 24);
  const bandGrowth = smooth((f - workingAt) / Math.max(1, nowAt - workingAt));
  const coralLeft = 970 - 535 * bandGrowth;
  const coralWidth = 105 + 535 * bandGrowth;
  const bandHeight = 30 + 31 * bandGrowth;
  const fanHaze = smooth((f - andAt) / Math.max(1, exactlyAt - andAt));
  const coolFocus = attention(coolAt, eastAt + 5);
  const eastFocus = attention(eastAt, suddenAt + 11);
  const finalWaterFocus = attention(rightAt, Math.min(durationInFrames - 1, pullEnd + 10)) * 0.14;
  const stageEnter = clamp(enter(0, 20));

  const normalColor = 'rgb(' + Math.round(25 + (213 - 25) * stopped) + ',' + Math.round(138 + (155 - 138) * stopped) + ',' + Math.round(113 + (37 - 113) * stopped) + ')';
  const compensationX = (zoom - 1) * width / (2 * zoom);
  const compensationY = (zoom - 1) * height / (2 * zoom);

  return (
    <AbsoluteFill style={{ background: 'linear-gradient(155deg, #F3F6F4 0%, #E5EFF5 46%, #DCECF3 76%, #FAFCF8 100%)', color: C.ink, overflow: "hidden", fontFamily: labelFont }}>
      <AbsoluteFill style={{ opacity: 0.4 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
      <AbsoluteFill style={{ background: 'radial-gradient(62% 74% at ' + (65 + Math.sin(f * 0.005) * 3) + '% 30%, rgba(40,175,205,0.19), transparent 72%), radial-gradient(44% 42% at 84% 85%, rgba(241,109,89,0.08), transparent 72%)' }} />

      <mg.CameraRig zoom={zoom} x={0} y={0}>
        {/* Correct a center-origin rig to the specified (position + pan) * zoom projection. */}
        <div style={{ position: "absolute", left: 0, top: 0, width, height, transform: 'translate(' + (panX + compensationX) + 'px,' + (panY + compensationY) + 'px)', transformOrigin: "0 0" }}>
          <div style={{ position: "absolute", left: 140, top: 180, width: 1640, height: 820, borderRadius: 28, background: 'linear-gradient(145deg, rgba(255,255,255,0.77), rgba(255,255,255,0.46) 58%, rgba(220,236,243,0.68))', backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.90)", boxShadow: glow, overflow: "hidden", opacity: 0.75 + stageEnter * 0.25 }}>
            <div style={{ position: "absolute", inset: 0, borderRadius: 28, background: 'radial-gradient(ellipse at 48% 31%, rgba(40,175,205,0.14), transparent 48%), radial-gradient(ellipse at 76% 81%, rgba(241,109,89,' + (0.035 + bandGrowth * 0.08) + '), transparent 42%)' }} />
          </div>

          <mg.Marker x={188} y={230} variant="cross" color={C.blue} />
          <mg.Marker x={1730} y={948} variant="cross" color={C.cyan} />
          <mg.Marker x={310} y={790} variant="cross" color={C.blue} />

          {/* The complete fan stays separate from the atmospheric lanes. */}
          <div style={{ position: "absolute", left: 630, top: 218, width: 600, height: 390, transform: 'translateY(' + ((1 - fanSpring) * 12) + 'px) scale(' + fanScale + ')', transformOrigin: "50% 64%", opacity: fanOpacity * (1 - fanHaze * 0.14) }}>
            <mg.Card width={600} height={390} tilt={-2} mode="light" style={{ position: "relative", padding: 0, borderRadius: 24, overflow: "visible", background: 'linear-gradient(145deg, rgba(255,255,255,0.82), rgba(220,242,249,0.62))', backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.95)", boxShadow: glow }}>
              <div style={{ position: "absolute", inset: 0, borderRadius: 24, background: 'radial-gradient(ellipse at 50% 38%, rgba(40,175,205,0.15), transparent 62%)' }} />
              <FanIllustration angle={angle} reveal={1} stopped={stopped} frame={f} />
            </mg.Card>
          </div>

          <div style={{ position: "absolute", left: 1110, top: 332, width: 280, height: 57, borderRadius: 24, background: "rgba(15,23,42,0.85)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.10)", boxShadow: "0 16px 40px rgba(0,102,255,0.25), 0 6px 16px rgba(20,45,64,0.16)", display: "flex", alignItems: "center", justifyContent: "center", color: "#F8FAFC", fontFamily: labelFont, fontSize: 26, fontWeight: 600, letterSpacing: 1.4, opacity: analogyOpacity }}>
            FAN = ANALOGY
          </div>

          {/* Compact operational evidence, not an invented measurement. */}
          <div style={{ position: "absolute", left: 1268, top: 429, width: 177, height: 110 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 11, fontSize: 23, fontWeight: 600, letterSpacing: 1.6, color: C.ink }}>
              <span style={{ width: 11, height: 11, borderRadius: 9999, background: normalColor, boxShadow: '0 0 17px ' + normalColor, display: "block" }} />
              ANALOGY
            </div>
            <div style={{ position: "relative", marginTop: 8, height: 40, fontSize: 30, fontWeight: 600, letterSpacing: -0.4 }}>
              <span style={{ position: "absolute", left: 0, top: 0, color: C.emerald, opacity: 1 - disruption }}>Turning</span>
              <span style={{ position: "absolute", left: 0, top: 0, color: C.amber, opacity: disruption * (1 - stopped) }}>Slowing</span>
              <span style={{ position: "absolute", left: 0, top: 0, color: C.amber, opacity: stopped }}>Stopped</span>
            </div>
          </div>

          <div style={{ position: "absolute", left: 352, top: 587, height: 34, display: "flex", alignItems: "center", gap: 17, opacity: 0.55 + laneReveal * 0.45 }}>
            <span style={{ fontSize: 29, fontWeight: 600, letterSpacing: 2.5, color: C.blue }}>WIND</span>
            <div style={{ position: "relative", width: 250, height: 33, fontSize: 24, color: C.ink }}>
              <span style={{ position: "absolute", inset: 0, opacity: 1 - windLabelMix }}>Westward flow</span>
              <span style={{ position: "absolute", inset: 0, opacity: windLabelMix }}>Weaker, still flowing</span>
            </div>
          </div>

          {[635, 669, 703].map((cy, lane) => (
            <div key={'lane-' + lane} style={{ position: "absolute", left: 350, top: cy - 12, width: 1100, height: 24, borderRadius: 9999, overflow: "hidden", background: 'linear-gradient(90deg, rgba(36,107,253,0.035), rgba(36,107,253,0.085) 60%, rgba(36,107,253,0.035))', border: "1px solid rgba(36,107,253,0.06)", opacity: (0.25 + laneReveal * 0.75) * (0.94 - fanHaze * 0.08) }}>
              {Array.from({ length: 11 }, (_, j) => {
                const period = 1296;
                const raw = j * 119 + lane * 49 + 71 - travel * (1 + lane * 0.035);
                const x = ((raw % period) + period) % period - 95;
                const survivor = (j + lane) % 3 === 0;
                const density = survivor ? 1 - disruption * 0.13 : 1 - smooth((f - (suddenAt + j % 3 * 5)) / Math.max(1, stopEnd - suddenAt - 10));
                const edgeFade = clamp((x + 55) / 75) * clamp((1100 - x) / 85);
                const len = 49 + (j % 3) * 9 - disruption * 9;
                return <div key={j} style={{ position: "absolute", left: x, top: 8 + (j % 2), width: len, height: 4, borderRadius: 9999, background: 'linear-gradient(90deg, ' + C.blue + ' 0%, rgba(36,107,253,0.78) 32%, rgba(36,107,253,0) 100%)', opacity: density * edgeFade * (0.75 + (j % 2) * 0.18), boxShadow: "-3px 0 9px rgba(0,102,255,0.21)" }} />;
              })}
            </div>
          ))}

          {/* No arrows in the water: temperature is encoded by a continuous band. */}
          <div style={{ position: "absolute", left: 350, top: 755, width: 1100, height: 120, borderRadius: 26, overflow: "hidden", background: 'linear-gradient(180deg, #69CAE0 0%, #3EADD7 45%, #297FC2 100%)', border: "1px solid rgba(255,255,255,0.84)", boxShadow: "0 20px 50px rgba(0,102,255,0.22), 0 8px 24px rgba(20,45,64,0.12)" }}>
            <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 49, borderRadius: 24, background: 'linear-gradient(180deg, rgba(210,253,255,0.91), rgba(40,175,205,0.94))', boxShadow: "0 6px 19px rgba(40,175,205,0.28)", opacity: 1 - bandGrowth * 0.08 }} />
            <div style={{ position: "absolute", left: 8, right: 8, top: 5, height: 7, borderRadius: 9999, background: "rgba(235,255,255,0.57)" }} />
            <div style={{ position: "absolute", left: 7, right: 7, top: 42, height: bandHeight, borderRadius: 24, background: 'linear-gradient(90deg, rgba(213,155,37,0.32) 0%, rgba(237,172,61,0.37) 38%, rgba(241,139,78,0.45) 79%, rgba(241,109,89,0.6) 100%)', boxShadow: "0 5px 21px rgba(241,109,89,0.17)" }} />
            <div style={{ position: "absolute", left: coralLeft - 68, top: 42, width: coralWidth + 68, height: bandHeight, borderRadius: 24, background: 'linear-gradient(90deg, rgba(241,109,89,0), rgba(241,109,89,0.34) 18%, rgba(241,109,89,0.76) 61%, rgba(241,109,89,0.94) 100%)', boxShadow: '10px 0 28px rgba(241,109,89,' + (0.15 + bandGrowth * 0.12) + ')' }} />
            <div style={{ position: "absolute", left: 22, right: 22, bottom: 11, height: 23, borderRadius: 20, background: 'linear-gradient(180deg, rgba(27,120,189,0), rgba(23,108,179,0.24))' }} />
            <div style={{ position: "absolute", left: 24, top: 13, fontSize: 26, lineHeight: "30px", fontWeight: 600, letterSpacing: 1.4, color: C.ink }}>SURFACE WATER</div>
            <div style={{ position: "absolute", left: 24, top: 75, fontSize: 27, lineHeight: "31px", fontWeight: 600, letterSpacing: 0.55, color: "#F8FAFC", textShadow: "0 2px 8px rgba(20,45,64,0.24)" }}>WESTERN PACIFIC</div>
            <div style={{ position: "absolute", right: 24, top: 75, fontSize: 27, lineHeight: "31px", fontWeight: 600, letterSpacing: 0.55, color: "#F8FAFC", textShadow: "0 2px 8px rgba(20,45,64,0.34)" }}>EASTERN PACIFIC</div>
          </div>

          <Selection x={347} y={752} width={1106} height={53} opacity={coolFocus} color={C.cyan} frameAt={coolAt} />
          <Selection x={1160} y={820} width={282} height={51} opacity={eastFocus} color={C.blue} frameAt={eastAt} />
          <div style={{ position: "absolute", left: 350, top: 755, width: 1100, height: 120, borderRadius: 26, pointerEvents: "none", boxShadow: '0 0 ' + (28 + 10 * Math.sin(f * 0.025)) + 'px rgba(241,109,89,' + finalWaterFocus + ')' }} />

          <div style={{ position: "absolute", left: 350, top: 936, fontSize: 20, letterSpacing: 2, fontWeight: 500, color: C.ink, opacity: 0.42 * (1 - smooth((f - suddenAt) / 25)) }}>
            SCHEMATIC · NOT TO SCALE
          </div>
        </div>
      </mg.CameraRig>

      {/* Editorial copy is deliberately fixed outside the camera. */}
      <mg.Heading kicker="PACIFIC CLIMATE / WIND SYSTEM" title="When the winds weaken" frameAt={2} style={{ position: "absolute", left: 112, top: 74, width: 970, maxWidth: 1000, color: C.ink, fontFamily: headingFont, fontSize: 56, fontWeight: 600, letterSpacing: -1.5, lineHeight: 1.1, pointerEvents: "none" }} />

      <AbsoluteFill style={{ pointerEvents: "none", mixBlendMode: "multiply" }}><mg.Noise opacity={0.028} /></AbsoluteFill>
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = {
  wordIndex?: number;
  index?: number;
  id?: number | string;
  startFrame?: number;
};

type ShotProps = {
  wordCues?: WordCue[];
  cleanedDisplaySentences?: unknown;
};

const BLUE = "#246BFD";
const CYAN = "#28AFCD";
const CORAL = "#F16D59";
const INK = "#142D40";
const SANS = "IBM Plex Sans, Arial, sans-serif";
const MONO = "IBM Plex Mono, monospace";
const TITLE = "Manrope, Arial, sans-serif";
const EASE = Easing.inOut(Easing.cubic);
const CLAMP = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const GLOW = "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(20,45,64,0.10)";

const smooth = (frame: number, start: number, end: number, from = 0, to = 1) =>
  interpolate(frame, [start, end], [from, to], { ...CLAMP, easing: EASE });

const readHeading = (input: unknown): string => {
  if (typeof input === "string") {
    const text = input.replace(/\s+/g, " ").trim();
    return text.length <= 42 ? text : "";
  }
  if (Array.isArray(input)) {
    for (const item of input) {
      const text = readHeading(item);
      if (text) return text;
    }
    return "";
  }
  if (input && typeof input === "object") {
    const item = input as Record<string, unknown>;
    return readHeading(item.title) || readHeading(item.displayText) || readHeading(item.text);
  }
  return "";
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1);
  const cueAt = (index: number, fallback: number): number => {
    const cue = cues.find((item) =>
      item.wordIndex === index || item.index === index || item.id === index || item.id === "W" + index
    );
    return typeof cue?.startFrame === "number" ? cue.startFrame : fallback;
  };

  const elAt = cueAt(25, 25);
  const superAt = cueAt(35, 170);
  const seeAt = cueAt(38, 233);
  const fanAt = cueAt(42, 292);
  const madeAt = cueAt(45, 337);
  const steadyAt = cueAt(48, 381);
  const windsAt = cueAt(49, 396);
  const tradeAt = cueAt(53, 456);
  const blowAt = cueAt(56, 500);
  const eastAt = cueAt(58, 530);
  const westAt = cueAt(60, 559);
  const trackAt = blowAt + 16;
  const pullAt = westAt + 16;
  const wideAt = pullAt + 18;

  const reveal = (at: number) => {
    if (f < at) return 0;
    const value = spring({ frame: f - at, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
    return Math.max(0, Math.min(1.05, value));
  };

  const zoom = interpolate(f, [0, seeAt, seeAt + 16, pullAt, wideAt], [1.2, 1.2, 1.15, 1.15, 1], { ...CLAMP, easing: EASE });
  const panX = interpolate(f, [0, seeAt + 16, blowAt, trackAt, pullAt, wideAt], [0, 0, 0, -60, 60, 0], { ...CLAMP, easing: EASE });
  const panY = interpolate(f, [0, seeAt, seeAt + 16, blowAt, wideAt], [52, 52, 4, 0, 0], { ...CLAMP, easing: EASE });
  const driftGate = smooth(f, seeAt + 16, seeAt + 40) * (1 - smooth(f, blowAt - 24, blowAt));
  const driftX = Math.sin((f - seeAt) / 72) * 5 * driftGate;
  const driftY = Math.sin((f - seeAt) / 89) * 2.5 * driftGate;
  const unthread = smooth(f, fanAt, madeAt + 44);
  const ringOpacity = 1 - smooth(f, fanAt + 16, madeAt + 38);
  const laneOpacity = 0.11 + 0.89 * smooth(f, seeAt, windsAt);
  const structuralOpacity = 0.12 + 0.88 * smooth(f, seeAt, madeAt + 16);
  const waterOpacity = 0.48 + 0.52 * smooth(f, seeAt, madeAt + 16);
  const tagIn = reveal(elAt);
  const tabIn = reveal(superAt);
  const tagY = interpolate(f, [0, fanAt, madeAt + 20], [365, 365, 315], { ...CLAMP, easing: EASE });
  const tradeIn = reveal(tradeAt);
  const suppliedHeading = readHeading(props.cleanedDisplaySentences);
  const headline = suppliedHeading || "El Niño";
  const stageScale = Math.min(width / 1920, height / 1080);

  const laneYs = [490, 560, 630];
  const ringRadii = [112, 126, 140];
  const connectors = [
    "M 800 424 C 800 450 840 458 840 490",
