type WordCue = { index?: number; wordIndex?: number; startFrame?: number; start?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };
const C = { ink: '#142D40', blue: '#246BFD', cyan: '#28AFCD', coral: '#F16D59', emerald: '#198A71', ocean: '#DCECF3' };
