const WATER = Array.from({ length: 22 }, (_, i) => ({ seed: random('water-phase-' + i), y: 20 + random('water-y-' + i) * 61, speed: 0.0021 + random('water-speed-' + i) * 0.0011, length: 35 + random('water-length-' + i) * 48 }));
const MOISTURE = Array.from({ length: 30 }, (_, i) => ({ seed: random('moisture-phase-' + i), x: 244 + random('moisture-x-' + i) * 314, speed: 0.006 + random('moisture-speed-' + i) * 0.003, radius: 1.8 + random('moisture-size-' + i) * 2.1 }));
const RAIN = Array.from({ length: 39 }, (_, i) => ({ seed: random('rain-phase-' + i), x: 208 + random('rain-x-' + i) * 438, speed: 0.012 + random('rain-speed-' + i) * 0.011, length: 10 + random('rain-length-' + i) * 13 }));

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueAt = (index: number, fallback: number) => {
    const cue = cues.find((c) => c.wordIndex === index || c.index === index) || (cues.length === 26 ? cues[index - 61] : undefined);
    return cue?.startFrame ?? (typeof cue?.start === 'number' ? Math.round(cue.start * fps) : fallback);
  };
  const t = { centuries: cueAt(62, 15), winds: cueAt(64, 52), help: cueAt(65, 71), sailing: cueAt(66, 90), ships: cueAt(67, 108), cross: cueAt(68, 127), pacific: cueAt(70, 164), oceanEnd: cueAt(71, 183) + 19, they: cueAt(72, 220), push: cueAt(73, 240), warm: cueAt(74, 260), surface: cueAt(75, 280), water: cueAt(76, 301), toward: cueAt(77, 321), indonesia: cueAt(78, 341), and: cueAt(79, 361), north: cueAt(80, 381), australia: cueAt(81, 402), where: cueAt(82, 422), fuels: cueAt(84, 462), tropical: cueAt(85, 482), rain: cueAt(86, 503) };
  const ramp = (a: number, b: number) => interpolate(frame, [a, Math.max(a + 1, b)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) });
  const snap = (at: number) => Math.min(1.055, Math.max(0, spring({ frame: frame - at, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } })));
  const envelope = (p: number) => Math.sin(Math.PI * p);
  const windIn = ramp(t.winds, t.help);
  const shipIn = ramp(t.sailing, t.ships + 7);
  const shipTravel = interpolate(frame, [t.ships, t.cross, t.oceanEnd], [0, 0.14, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) });
  const waterIn = ramp(t.push, t.warm + 12);
  const waterGrow = ramp(t.warm, t.indonesia + 16);
  const poolIn = ramp(t.toward, t.australia + 12);
  const context = ramp(t.they, t.warm);
