  const moistureIn = ramp(t.where, t.fuels + 17);
  const zoom = interpolate(frame, [0, t.help, t.oceanEnd, t.they, t.warm, t.and, t.north + 1, t.where], [1.25, 1.18, 1.18, 1.18, 1.12, 1.12, 1.12, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) });
  const panX = interpolate(frame, [0, t.help, t.oceanEnd, t.they, t.warm, t.toward, t.and, t.north + 1, t.where], [-64, -64, 6, 6, 0, 0, 60, 60, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) });
  const panY = interpolate(frame, [0, t.help, t.oceanEnd, t.warm, t.and, t.where], [10, 6, -6, 0, -8, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) });
  const shipX = 1200 - shipTravel * 420;
  const shipY = 384 - Math.sin(shipTravel * Math.PI) * 24;
