  const progress = (a: number, b: number) => interpolate(frame, [a, Math.max(a + 1, b)], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
  const reveal = (at: number) => frame < at ? 0 : clamp(spring({ frame: frame - at, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } }));
  const push = progress(cueAt(111), cueAt(113) + 1);
  const returnWide = progress(cueAt(123), cueAt(125) + 1);
  const finale = progress(cueAt(142), cueAt(143) + 1);
  const drift = progress(cueAt(125) + 1, cueAt(142));
  const initial = mix(1.04, 1, progress(2, 20));
  const zoom = (initial + 0.12 * push - 0.07 * returnWide + 0.003 * drift) * (1 - finale) + finale;
  const panX = (12 * push - 60 * progress(cueAt(116), cueAt(121) + 18)) * (1 - returnWide) + 5 * drift * (1 - finale);
  const panY = -4 * push * (1 - returnWide) - 2 * drift * (1 - finale);
  const pivotX = 704;
  const pivotY = 600;
  // Compensate CameraRig's center pivot. The continuous rig focuses on the transect.
