import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from 'remotion';
import { mg } from '@frame60/mg';

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };
type OutcomeKind = 'temperature' | 'rain' | 'flood' | 'dry';
type Outcome = { id: string; title: string; result: string; x: number; y: number; color: string; kind: OutcomeKind; reveal: number; focus: number; animate: number; packet: number; arrival: number; path: string; shadow: string };

const C = { ink: '#142D40', blue: '#0066FF', wind: '#246BFD', cyan: '#28AFCD', coral: '#F16D59', emerald: '#198A71', amber: '#F59E0B', white: '#F8FAFC' };
const sans = 'IBM Plex Sans, sans-serif';
const mono = 'IBM Plex Mono, monospace';
const clampOptions = { extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const };
const ease = Easing.inOut(Easing.cubic);

const Diagram: React.FC<{ kind: OutcomeKind; progress: number; frame: number; color: string }> = ({ kind, progress, frame, color }) => {
  if (kind === 'temperature') {
    return (
      <div style={{ position: 'relative', height: 46 }}>
        <div style={{ position: 'absolute', left: 2, right: 2, top: 4, height: 18, borderRadius: 24, overflow: 'hidden', background: 'rgba(255,255,255,0.07)' }}>
          <div style={{ position: 'absolute', left: '28%', top: 0, height: 18, width: 12 + progress * 182, borderRadius: 24, background: 'linear-gradient(90deg, rgba(40,175,205,0.25), #F16D59)', boxShadow: '0 0 16px rgba(241,109,89,0.35)' }} />
        </div>
        <div style={{ position: 'absolute', left: 86, top: 0, width: 2, height: 27, borderRadius: 24, background: 'rgba(248,250,252,0.65)' }} />
        <div style={{ position: 'absolute', left: 85 + progress * 174, top: 1, width: 6, height: 25, borderRadius: 24, background: color, boxShadow: '0 0 15px rgba(241,109,89,0.6)' }} />
        <span style={{ position: 'absolute', left: 0, top: 28, fontSize: 15, color: '#C3D5E7' }}>Reference</span>
        <span style={{ position: 'absolute', right: 0, top: 28, fontSize: 15, color }}>Warmer</span>
      </div>
