  }
  if (kind === 'rain') {
    return (
      <div style={{ position: 'relative', height: 46, borderRadius: 24, overflow: 'hidden', background: 'linear-gradient(180deg, rgba(0,102,255,0.05), rgba(0,102,255,0.22))', border: '1px solid rgba(59,130,246,0.22)' }}>
        {Array.from({ length: 27 }, (_, i) => {
          const strength = i < 5 ? 0.30 : interpolate(progress, [(i - 5) / 30, (i - 5) / 30 + 0.23], [0.02, 0.85], clampOptions);
          const y = ((frame * (0.32 + (i % 3) * 0.09) + i * 17) % 72) - 25;
          return <div key={i} style={{ position: 'absolute', left: 10 + i * 11, top: y, width: 2.5, height: 12 + (i % 4) * 4, borderRadius: 24, background: 'linear-gradient(180deg, rgba(59,130,246,0), #69B8FF)', opacity: strength, boxShadow: '0 0 5px rgba(0,102,255,0.4)' }} />;
        })}
      </div>
    );
  }
  if (kind === 'flood') {
    const level = 8 + progress * 30;
    return (
      <div style={{ position: 'relative', height: 46, borderRadius: 24, overflow: 'hidden', background: 'rgba(0,102,255,0.06)', border: '1px solid rgba(59,130,246,0.25)' }}>
