    );
  }
  const remaining = 36 - progress * 19;
  return (
    <div style={{ position: 'relative', height: 46, borderRadius: 24, overflow: 'hidden', background: 'rgba(245,158,11,0.06)', border: '1px solid rgba(245,158,11,0.23)' }}>
