  );
};

const OutcomePanel: React.FC<{ item: Outcome; frame: number; fps: number }> = ({ item, frame, fps }) => {
  const visible = interpolate(frame, [item.reveal, item.reveal + 12], [0, 1], clampOptions);
  const rise = spring({ frame: Math.max(0, frame - item.reveal), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const evidence = interpolate(frame, [item.animate, item.animate + (item.kind === 'dry' ? 48 : 54)], [0, 1], { ...clampOptions, easing: ease });
  const focused = interpolate(frame, [item.focus, item.focus + 7, item.focus + 58, item.focus + 76], [0, 1, 1, 0], clampOptions);
  return (
