import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = {
  wordIndex?: number;
  globalIndex?: number;
  index?: number;
  startFrame?: number;
  word?: string;
  text?: string;
};
type ShotProps = { wordCues?: WordCue[] };

const C = {
  porcelain: "#F3F6F4",
  ice: "#DCECF3",
  ink: "#142D40",
  blue: "#246BFD",
  cyan: "#28AFCD",
  coral: "#F16D59",
  emerald: "#198A71",
  amber: "#D59B25",
  amberInk: "#78500E",
};
const sans = "'IBM Plex Sans', sans-serif";
const mono = "'IBM Plex Mono', monospace";
const headingFont = "Manrope, sans-serif";
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const cueWords = ["in", "the", "1870s", "a", "powerful", "el", "nino", "was", "one", "of", "the", "factors", "behind", "a", "famine", "that", "took", "the", "lives", "of", "an", "estimated", "3", "of", "the", "worlds", "population"];
const normalize = (value: string) => value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, "");

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.max(0, Math.min(frame, durationInFrames - 1));
  const cueAt = (wordIndex: number, fallback: number) => {
    const direct = cues.find((cue) => cue.wordIndex === wordIndex || cue.globalIndex === wordIndex || cue.index === wordIndex);
    const local = cues.length === 27 ? cues[wordIndex - 172] : undefined;
    const byText = cues.find((cue) => normalize(cue.word || cue.text || "") === cueWords[wordIndex - 172]);
    const value = (direct || local || byText)?.startFrame;
    return typeof value === "number" && value >= 0 && value < durationInFrames ? value : fallback;
  };
  const dateAt = cueAt(174, 26);
  const powerfulAt = cueAt(176, 56);
  const elAt = cueAt(177, 71);
  const qualificationAt = cueAt(180, 115);
  const factorsAt = cueAt(183, 160);
  const behindAt = cueAt(184, 175);
  const famineAt = cueAt(186, 205);
  const livesAt = cueAt(190, 265);
  const estimatedAt = cueAt(193, 309);
  const numberAt = cueAt(194, 324);
  const worldAt = cueAt(197, 369);
  const populationAt = cueAt(198, 384);
  const fade = (at: number, length = 12) => interpolate(f, [at, at + length], [0, 1], clamp);
  const pop = (at: number) => spring({ frame: Math.max(0, f - at), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const ease = Easing.inOut(Easing.cubic);
  const zoom = interpolate(f, [0, 99, 100, 191, 221, 310, 356, 420, 438], [1, 1.03, 1.03, 1.18, 1.18, 1, 1, 1.01, 1.01], { ...clamp, easing: ease });
  const panX = interpolate(f, [0, 100, 191, 221, 310, 438], [0, 0, 55, 55, 0, 0], { ...clamp, easing: ease });
  const stageScale = Math.min(width / 1920, height / 1080);
  const enter = fade(0, 16);
  const dateP = pop(dateAt);
  const elP = pop(elAt);
  const qP = pop(qualificationAt);
  const famineP = pop(famineAt);
  const estimateP = pop(estimatedAt);
  const shownShare = interpolate(f, [numberAt, numberAt + 10], [0, 3], clamp);
  const beamOn = fade(livesAt, 14) * (1 - fade(numberAt + 22, 30));
  const beamY = interpolate(f, [livesAt, estimatedAt, numberAt + 20], [252, 529, 626], { ...clamp, easing: Easing.inOut(Easing.quad) });
  const reticleOpacity = fade(estimatedAt, 12);
  const reticleP = pop(estimatedAt);
  const pulse = f < numberAt ? 0 : ((f - numberAt) % 90) / 90;
  const packetProgress = f < factorsAt ? 0 : ((f - factorsAt) % 94) / 94;
  const inspectionGate = fade(estimatedAt, 12);
  const traceShadow = "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.12)";
  const glass: React.CSSProperties = {
    background: "rgba(15,23,42,0.85)",
    border: "1px solid rgba(255,255,255,0.10)",
    backdropFilter: "blur(14px)",
    borderRadius: 24,
    boxShadow: traceShadow,
    color: "#F8FAFC",
  };

  return (
    <AbsoluteFill style={{ background: C.porcelain, overflow: "hidden", fontFamily: sans }}>
      <div style={{ position: "absolute", left: (width - 1920 * stageScale) / 2, top: (height - 1080 * stageScale) / 2, width: 1920, height: 1080, transform: "scale(" + stageScale + ")", transformOrigin: "0 0" }}>
        <AbsoluteFill style={{ background: "linear-gradient(148deg, #FAFCF7 0%, #F3F6F4 32%, #DCECF3 73%, #EDF3FB 100%)" }} />
        <AbsoluteFill style={{ opacity: 0.43 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
        <AbsoluteFill style={{ background: "radial-gradient(ellipse at 74% 28%, rgba(36,107,253,0.13) 0%, transparent 58%), radial-gradient(ellipse at 30% 68%, rgba(213,155,37,0.12) 0%, transparent 60%), radial-gradient(ellipse at 46% 8%, rgba(255,255,255,0.92) 0%, transparent 70%)", transform: "translateX(" + interpolate(f, [0, 437], [-12, 12], clamp) + "px)" }} />

