    const positional = cues.length === 28 ? cues[index - 199] : undefined;
    const start = (found ?? positional)?.startFrame;
    return typeof start === 'number' && Number.isFinite(start) ? start : WORD_STARTS[index];
  };
  const progress = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], bounded);
