import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };
const C = { ink: '#142D40', blue: '#246BFD', cyan: '#28AFCD', coral: '#F16D59', violet: '#8B5CF6', amber: '#D59B25', emerald: '#198A71' };
const ease = Easing.inOut(Easing.cubic);
const sans = 'IBM Plex Sans, sans-serif';
const mono = 'IBM Plex Mono, monospace';

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueAt = (index: number, fallback: number, word: string) => {
    const found = cues.find((cue) => cue.wordIndex === index || cue.index === index) || cues.find((cue) => (cue.word || cue.text || '').toLowerCase().replace(/[^a-z0-9]/g, '') === word);
    return typeof found?.startFrame === 'number' ? found.startFrame : fallback;
  };
  const oceanAt = cueAt(229, 34, 'ocean');
  const releaseAt = cueAt(230, 53, 'releases');
  const heatAt = cueAt(231, 72, 'heat');
  const atmosphereAt = cueAt(234, 128, 'atmosphere');
  const contextAt = cueAt(235, 147, 'and');
  const raisesAt = cueAt(236, 166, 'raises');
  const globalAt = cueAt(237, 185, 'global');
  const temperatureAt = cueAt(238, 203, 'temperatures');
  const yearAt = cueAt(239, 222, '2027');
  const couldAt = cueAt(240, 241, 'could');
  const hottestAt = cueAt(243, 298, 'hottest');
  const recordedAt = cueAt(246, 354, 'recorded');
  const ramp = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
  const enter = (start: number) => spring({ frame: Math.max(0, frame - start), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const follow = ramp(releaseAt, releaseAt + 18);
  const track = ramp(releaseAt, contextAt);
  const pullback = ramp(contextAt, 223);
  const drift = ramp(223, Math.max(224, durationInFrames - 1));
  const zoom = (1.22 - 0.04 * follow) * (1 - pullback) + (1 + 0.03 * drift) * pullback;
  const panX = 30 * (1 - pullback);
  const panY = (-10 + 45 * track) * (1 - pullback);
  const release = ramp(releaseAt, heatAt + 12);
  const heat = ramp(heatAt, atmosphereAt + 18);
  const spread = ramp(atmosphereAt, temperatureAt + 20);
  const rise = ramp(raisesAt, yearAt + 12);
  const yearReveal = frame >= yearAt ? enter(yearAt) : 0;
  const conditional = ramp(couldAt, couldAt + 16);
  const recordFocus = ramp(hottestAt, hottestAt + 16);
  const settled = ramp(recordedAt, recordedAt + 18);
  const gaugeHeight = 76 + 160 * rise;
  const wave = frame * 2.1;
  const designScale = Math.min(width / 1920, height / 1080);
  const glassShadow = '0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.08)';
  const warmShadow = '0 20px 60px rgba(255,90,54,0.2), 0 8px 24px rgba(0,0,0,0.12)';

  return (
    <AbsoluteFill style={{ background: 'linear-gradient(155deg, #F3F6F4 0%, #DCECF3 54%, #F8FAFC 100%)', overflow: 'hidden', color: C.ink, fontFamily: sans }}>
