        <mg.Marker x={148} y={960} variant="cross" color={C.blue} />
        <mg.Marker x={1768} y={202} variant="cross" color={C.coral} />
        <mg.Marker x={1768} y={960} variant="cross" color={C.blue} />

        <mg.CameraRig zoom={zoom} x={panX} y={panY}>
          <div style={{ position: 'absolute', left: 340, top: 290, width: 1080, height: 340, borderRadius: 28, overflow: 'hidden', background: 'rgba(255,255,255,0.75)', backdropFilter: 'blur(14px)', border: '1px solid rgba(0,0,0,0.08)', boxShadow: glassShadow }}>
            <div style={{ position: 'absolute', inset: 0, borderRadius: 28, background: 'linear-gradient(120deg, rgba(40,175,205,0.16), rgba(255,255,255,0.18) 45%, rgba(241,109,89,0.12))' }} />
            <div style={{ position: 'absolute', inset: '12px 20px', borderRadius: 24, overflow: 'hidden', opacity: 0.13 + 0.07 * ramp(globalAt, globalAt + 18), pointerEvents: 'none' }}>
              <mg.MapStage theme="light" dimInactive={false} camera={{ sequence: [{ atFrame: 0, focus: [180, 0], zoom: 1.0 }] }} />
            </div>
            <div style={{ position: 'absolute', left: 70, right: 70, top: 64, bottom: 18, borderRadius: 28, opacity: spread * 0.7, transform: `scaleX(${0.45 + 0.55 * spread})`, background: 'radial-gradient(ellipse at 50% 75%, rgba(241,109,89,0.26), rgba(241,109,89,0.09) 45%, transparent 75%)' }} />
            <div style={{ position: 'absolute', left: 24, top: 23, height: 54, padding: '0 20px', display: 'flex', alignItems: 'center', gap: 12, borderRadius: 9999, background: 'rgba(255,255,255,0.84)', border: '1px solid rgba(0,0,0,0.06)', boxShadow: '0 8px 24px rgba(0,102,255,0.10)' }}>
