            <div style={{ position: 'absolute', left: -120, right: -120, top: 26, height: 32, borderRadius: 24, transform: `translateX(${Math.sin(frame / 66) * 35}px)`, background: 'linear-gradient(90deg, rgba(255,157,123,0.14), rgba(255,179,148,0.66), rgba(255,157,123,0.12))', filter: 'blur(9px)' }} />
            {[0, 1, 2].map((i) => (
